package com.studenttong.mobile;
import android.content.*;import android.webkit.*;import java.io.*;import java.net.*;import javax.net.ssl.*;import java.util.*;
/** Only fetches visible map tiles; bounded account-local HTTP cache, no bulk/offline download. */
public final class MapTiles {
 final File directory;final String template;public MapTiles(Context c,String aid,String template)throws Exception{this.template=validate(template);if(!aid.matches("[a-f0-9-]{36}"))throw new Exception("无效账号");directory=new File(c.getCacheDir(),"map-tiles/"+aid);directory.mkdirs();}
 public static String validate(String template)throws Exception{if(!template.contains("{z}")||!template.contains("{x}")||!template.contains("{y}"))throw new Exception("瓦片模板须含{z}/{x}/{y}");URI u=new URI(template.replace("{z}","0").replace("{x}","0").replace("{y}","0"));if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null)throw new Exception("瓦片必须是无凭据的HTTPS地址");return template;}
 public boolean matches(String url){String regex=java.util.regex.Pattern.quote(template).replace("{z}","\\E[0-9]+\\Q").replace("{x}","\\E[0-9]+\\Q").replace("{y}","\\E[0-9]+\\Q");return url.matches(regex);}
 public WebResourceResponse get(String url){try{if(!matches(url))throw new Exception();File file=new File(directory,UUID.nameUUIDFromBytes(url.getBytes("UTF-8"))+".png");if(file.isFile()&&file.lastModified()>System.currentTimeMillis())return image(new FileInputStream(file));HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","StudentTong/0.3.0 (https://github.com/saldienses/StudentTong)");c.setRequestProperty("Referer","https://github.com/saldienses/StudentTong");try{if(c.getResponseCode()!=200)throw new Exception();byte[] data;try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>1024*1024)throw new IOException();out.write(b,0,n);}data=out.toByteArray();}if(data.length<8||data[0]!=(byte)137||data[1]!=80||data[2]!=78||data[3]!=71)throw new IOException();String cache=c.getHeaderField("Cache-Control");if(cache==null||!cache.contains("no-store")){long seconds=604800;java.util.regex.Matcher m=java.util.regex.Pattern.compile("max-age=([0-9]+)").matcher(cache==null?"":cache);if(m.find())seconds=Math.min(2592000,Long.parseLong(m.group(1)));try(FileOutputStream out=new FileOutputStream(file)){out.write(data);}file.setLastModified(System.currentTimeMillis()+seconds*1000);File[] files=directory.listFiles();if(files!=null&&files.length>350){Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(int k=0;k<Math.min(30,files.length);k++)files[k].delete();}}return image(new ByteArrayInputStream(data));}finally{c.disconnect();}}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",503,"Unavailable",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}}
 WebResourceResponse image(InputStream data){return new WebResourceResponse("image/png",null,200,"OK",Collections.singletonMap("Access-Control-Allow-Origin","https://studenttong-map.local"),data);}
}
